; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: cpcmin (Amstrad CPC - minimal firmware (own screen and keys, firmware for discs and ROMs)), starts in normal mode
; ============================================================

			DEVICE AMSTRADCPC6128		; for SAVEAMSDOS at the end
			org #0040

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 255		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 1		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 1		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)

ntc_start:
			di
			call ntc_rj_find		; Library: ROM - find the ROM, patch the jump block
			jr nc, ntc_rj_ok
			ei
			ret				; no ROM (the message is shown): back to the caller
ntc_rj_ok:
			di				; (KL ROM SELECT lets interrupts in again)
			ld hl, ntc_rj_exit
			push hl			; End comes back here: the caller's ROM selection again
			ld (ntc_csp), sp
			ld a, (#BC77)		; Option RomEnable: start the ROMs again
			cp #DF			; AMSDOS has the cassette calls: they are running
			jr z, ntc_roms_on
			ei
			ld de, ntc_free		; the lowest address the ROMs may use (above the arrays)
			ld hl, #ABFF		; the highest (as usual for AMSDOS: it takes about #A700-#ABFF)
			ld c, 7
			call #BCCE		; KL INIT BACK: ROM 7 (DE / HL come back as the new limits)
			di
			ASSERT ntc_free <= #A600, "Option RomEnable: the program and its arrays must end below #A600 (the ROMs take their RAM from #ABFF down)"
ntc_roms_on:
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld ix, ntc_go
			jp ntc_plat_irqon		; interrupt handler for normal mode
ntc_go:
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dw kw_scrinit		; mode 1, ROMs off, clear screen

			; Main.bas 25: Title.Show
			dw p_title_show_c

			; Main.bas 26: Level1.Play
			dw p_level1_play_c

			; Main.bas 27: Level2.Play
			dw p_level2_play_c

			; Main.bas 28: Level1.Play
			dw p_level1_play_c

			; Main.bas 29: Print "Maths from main: 7 squared is "; Maths.Square(7)
			dw p_maths_square_c, lit_7
			dw kw_printzoscii
			dw glyph_4D, glyph_61, glyph_74, glyph_68, glyph_73, glyph_20, glyph_66, glyph_72
			dw glyph_6F, glyph_6D, glyph_20, glyph_6D, glyph_61, glyph_69, glyph_6E, glyph_3A
			dw glyph_20, glyph_37, glyph_20, glyph_73, glyph_71, glyph_75, glyph_61, glyph_72
			dw glyph_65, glyph_64, glyph_20, glyph_69, glyph_73, glyph_20, 0		; "Maths from main: 7 squared is "
			dw kw_printint, var_maths_square_square
			dw kw_printnl

			; Main.bas 30: Print "Stars from main (Stage1's copy): "; Stars.Count()
			dw p_stars_count_c
			dw kw_printzoscii
			dw glyph_53, glyph_74, glyph_61, glyph_72, glyph_73, glyph_20, glyph_66, glyph_72
			dw glyph_6F, glyph_6D, glyph_20, glyph_6D, glyph_61, glyph_69, glyph_6E, glyph_20
			dw glyph_28, glyph_53, glyph_74, glyph_61, glyph_67, glyph_65, glyph_31, glyph_27
			dw glyph_73, glyph_20, glyph_63, glyph_6F, glyph_70, glyph_79, glyph_29, glyph_3A
			dw glyph_20, 0		; "Stars from main (Stage1's copy): "
			dw kw_printint, var_stars_count_count
			dw kw_printnl

			; Main.bas 31: Credits.Show
			dw p_credits_show_c

			; Main.bas 32: End
			dw kw_printnl0
			dw kw_printzoscii
			dw glyph_50, glyph_72, glyph_65, glyph_73, glyph_73, glyph_20, glyph_61, glyph_20
			dw glyph_6B, glyph_65, glyph_79, 0		; "Press a key"
			dw kw_waitkey
			dw kw_stop

