; ============================================================
; Keyword library (rom)
; ============================================================

; Library: ROM - the keyword library is in the ROM NTC CPCMIN (NTCMIN.ROM).
; Its routines: this jump block, the numbers made into addresses by the ROM at the start.
; Its variables and constants: fixed addresses (RAM #8800 - #A5EF is the ROM's).
ntc_rj_block:
kw_stop:		jp 1
ntc_xn:		jp 2
kw_next1l_n:	jp 31
kw_ltov:		jp 47
kw_vtov:		jp 48
kw_inc:		jp 51
kw_add:		jp 53
kw_mulvv:	jp 60
kw_printzoscii:	jp 129
kw_printint:	jp 132
kw_printnl0:	jp 135
kw_printnl:	jp 139
kw_scrinit:	jp 147
mem_sel:		jp 259
ntc_ovl_enter:	jp 277
ntc_ovl_enterc:	jp 278
ntc_plat_irqon:	jp 316
kw_waitkey:	jp 344
NTC_RJ_N	equ 18		; entries
ntc_csp	equ #8800		; ROM data
ntc_font	equ #948E		; ROM bss
ntc_nmode	equ #8807		; ROM data
ntc_ovl_body	equ #8898		; ROM data
ntc_ovl_lc	equ #8897		; ROM data
ntc_v_free	equ #896F		; ROM data
ntc_v_romen	equ #8975		; ROM data
ntc_v_romold	equ #8977		; ROM data
ntc_v_stamp	equ #8973		; ROM data
ntc_v_start	equ #8971		; ROM data
			ASSERT ntc_free <= #8800, "Library: ROM - the program and its arrays must end below #8800 (the ROM's RAM)"

; the start: find the ROM set in slots 0 - 31 (its main ROM, then the others with the same
; stamp), have the main one patch the jump block. NC = ready; C = not there / too old
; (the message is shown, the caller's ROM selection is back)
ntc_rj_find:
			ld c, 0
			call #B90F		; KL ROM SELECT: B / C = the caller's state and selection
			ld (ntc_rj_old), bc
			xor a
			ld (ntc_rj_want), a
			call ntc_rj_scan		; the main ROM
			jp c, ntc_rj_nf
			ld (ntc_rj_slots), a
			ld e, (hl)
			inc hl
			ld d, (hl)			; its patcher
			ld (ntc_rj_call + 1), de
			ld a, 1
ntc_rj_more:				; the other ROMs of the set
			ld (ntc_rj_want), a
			ld hl, ntc_rj_n
			cp (hl)
			jr nc, ntc_rj_all
			call ntc_rj_scan
			jp c, ntc_rj_part
			ld b, a
			ld a, (ntc_rj_want)
			ld e, a
			ld d, 0
			ld hl, ntc_rj_slots
			add hl, de
			ld (hl), b
			inc a
			jr ntc_rj_more
ntc_rj_all:
			ld a, (ntc_rj_slots)
			ld c, a
			call #B90F		; KL ROM SELECT: the main ROM
			di					; (KL ROM SELECT lets interrupts in)
			ld a, (ntc_rj_slots)	; its slot
			ld hl, ntc_rj_block
			ld bc, NTC_RJ_N
			ld de, ntc_rj_slots
ntc_rj_call:
			call 0				; HL = jump block, BC = entries, A = slot, DE = slots; C: DE = a number it hasn't got
			jp c, ntc_rj_lacks
			ld hl, ntc_free
			ld (ntc_v_free), hl
			ld hl, ntc_start
			ld (ntc_v_start), hl
			ld hl, NTC_STAMP
			ld (ntc_v_stamp), hl
			ld a, 1
			ld (ntc_v_romen), a
			ld a, (ntc_rj_old)
			ld (ntc_v_romold), a
			or a				; NC: ready
			ret
; ntc_rj_scan - a ROM of the set: ROM ntc_rj_want (0 = the main one, any stamp; the others
; with the main one's stamp). NC: A = its slot, HL = past its block's count byte (the main
; one: at its patcher), it is selected. C: not there
ntc_rj_scan:
			ld c, 0
ntc_rj_next:
			push bc
			call #B90F		; KL ROM SELECT: ROM C
			pop bc
			ld a, (#C000)
			cp 1				; a background ROM?
			jr nz, ntc_rj_skip
			ld hl, (#C004)		; its names
			ld a, h
			cp #C0
			jr c, ntc_rj_skip
ntc_rj_name:
			ld a, (hl)
			inc hl
			or a
			jr nz, ntc_rj_name		; to the 0 after the names
			ld de, ntc_rj_sig
			ld b, ntc_rj_sige - ntc_rj_sig
ntc_rj_cmp:
			ld a, (de)
			cp (hl)
			jr nz, ntc_rj_skip
			inc de
			inc hl
			djnz ntc_rj_cmp
			ld e, (hl)
			inc hl
			ld d, (hl)			; DE = its set's stamp
			inc hl
			ld a, (ntc_rj_want)
			cp (hl)				; its place in the set
			jr nz, ntc_rj_skip
			or a
			jr z, ntc_rj_got
			push hl
			ld hl, (ntc_rj_set)
			or a
			sbc hl, de
			pop hl
			jr nz, ntc_rj_skip		; another build's
ntc_rj_got:
			ld (ntc_rj_set), de
			inc hl
			ld a, (hl)
			ld (ntc_rj_n), a		; ROMs in the set
			inc hl
			ld a, c
			or a				; NC
			ret
ntc_rj_skip:
			inc c
			ld a, c
			cp 32
			jr c, ntc_rj_next
			scf					; C: not there
			ret
ntc_rj_nf:
			ld hl, ntc_rj_tnf
			jr ntc_rj_fail
ntc_rj_part:				; a ROM of the set is missing: its number (1 = the main one)
			ld a, (ntc_rj_want)
			inc a
			ld e, a
			ld d, 0
			ld (ntc_rj_num), de
			ld hl, ntc_rj_tpt
			jr ntc_rj_fnum
ntc_rj_lacks:
			ld (ntc_rj_num), de
			ld hl, ntc_rj_tlk
ntc_rj_fnum:
			ld a, 1
			ld (ntc_rj_pn), a		; the number after the message
ntc_rj_fail:
			push hl
			ld bc, (ntc_rj_old)
			call #B918		; KL ROM DESELECT: the caller's selection again
			pop hl
			call ntc_rj_puts
			ld a, (ntc_rj_pn)
			or a
			jr z, ntc_rj_nl
			ld a, (ntc_rj_num + 1)
			call ntc_rj_hex
			ld a, (ntc_rj_num)
			call ntc_rj_hex
ntc_rj_nl:
			ld hl, ntc_rj_tnl
			call ntc_rj_puts
			ei
			call #BB06		; KM WAIT CHAR: a key first (a RUN" program's return resets the machine)
			di
			scf
			ret
ntc_rj_puts:				; HL = text, 0 ends; DE = its start
			ld d, h
			ld e, l
ntc_rj_pl:
			ld a, (hl)
			or a
			ret z
			call #BB5A		; TXT OUTPUT
			inc hl
			jr ntc_rj_pl
ntc_rj_hex:
			push af
			rrca
			rrca
			rrca
			rrca
			call ntc_rj_dig
			pop af
ntc_rj_dig:
			and 15
			add a, #90
			daa
			adc a, #40
			daa
			jp #BB5A
; End: the caller's ROM selection again, then back to the caller
ntc_rj_exit:
			ld bc, (ntc_rj_old)
			call #B918		; KL ROM DESELECT
			ret
ntc_rj_old:		dw 0			; the caller's ROM selection (C) and state (B)
ntc_rj_num:		dw 0
ntc_rj_pn:		db 0			; 1 = a number goes after the message
ntc_rj_want:	db 0			; the ROM of the set looked for
ntc_rj_n:		db 1			; ROMs in the set
ntc_rj_set:		dw 0			; the set's stamp
ntc_rj_slots:	ds 8			; each ROM's slot, the main one first
ntc_rj_sig:		db "NTC", 2, "CPCMIN", 0	; the ROMs' NTC block
ntc_rj_sige:
ntc_rj_tnf:		db "ROM NTC CPCMIN (NTCMIN.ROM) not found", 0
ntc_rj_tlk:		db "ROM NTC CPCMIN too old: no routine #", 0
ntc_rj_tpt:		db "ROM NTCMIN<n>.ROM not found: n = #", 0
ntc_rj_tnl:		db 13, 10, "Press a key", 13, 10, 0

; pages (Option Page / Option Class Overlay): the RAM page each is loaded in (0 = not loaded),
; the end of its code and the size of its page variables, its file and its name
ovl_blk_intro:	dw 0, ovl_intro_end, ovl_intro_vsize
			db "PAGES.001", 0, "Intro", 0	; its file, its name (for the messages)
ovl_blk_stage1:	dw 0, ovl_stage1_end, ovl_stage1_vsize
			db "PAGES.002", 0, "Stage1", 0	; its file, its name (for the messages)
ovl_blk_stage2:	dw 0, ovl_stage2_end, ovl_stage2_vsize
			db "PAGES.003", 0, "Stage2", 0	; its file, its name (for the messages)
ovl_blk_ending:	dw 0, ovl_ending_end, ovl_ending_vsize
			db "PAGES.004", 0, "Ending", 0	; its file, its name (for the messages)
; classes in more than one page: for each procedure, its copies (the home first): page, body
p_maths_square_ct:	db 2
			dw ovl_blk_stage1, p_maths_square
			dw ovl_blk_stage2, p_maths_square__stage2
p_stars_add_ct:	db 1		; paged variables: the home copy only
			dw ovl_blk_stage1, p_stars_add
p_stars_count_ct:	db 1		; paged variables: the home copy only
			dw ovl_blk_stage1, p_stars_count

ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bss		equ ntc_end
ntc_bss_size	equ 0
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
; Option Reserve: the program and its arrays (ntc_start .. ntc_free) must stay out of these
			ASSERT (ntc_free <= 16384) || (ntc_start >= 32768), "the program (or its arrays) reaches into Option Reserve #4000-#7FFF (Main.bas line 23)"
			SAVEAMSDOS "PAGES.BIN", ntc_start, ntc_end - ntc_start, ntc_start
			ASSERT (ntc_free <= #4000) || (ntc_start >= #8000), "overlay classes: the program and its arrays must stay out of #4000-#7FFF (the window they run in)"

; ============================================================
; Page Intro -> PAGES.001: title - threads built to run at #4000
; (a RAM page, or the overlay area); their variables are in the program, but for
; Private Paged ones (after the code). Written as its own file.
; ============================================================
			ORG #4000
ovl_intro_start:
			dw NTC_STAMP		; the build stamp: the loader checks it against the program's
ovl_intro__0_s:		; title
p_title_show:

			; Title.cls 3: Print "== PAGES DEMO =="
			dw kw_printzoscii
			dw glyph_3D, glyph_3D, glyph_20, glyph_50, glyph_41, glyph_47, glyph_45, glyph_53
			dw glyph_20, glyph_44, glyph_45, glyph_4D, glyph_4F, glyph_20, glyph_3D, glyph_3D
			dw 1, 0		; "== PAGES DEMO ==\n"

			; Title.cls 4: Print "Score: "; Score.Total()
			dw p_score_total_c
			dw kw_printzoscii
			dw glyph_53, glyph_63, glyph_6F, glyph_72, glyph_65, glyph_3A, glyph_20, 0		; "Score: "
			dw kw_printint, var_score_total_total
			dw kw_printnl
			dw p_title_show_r
ovl_intro__0_e:
			dw 0			; (never empty)
ovl_intro_end:		; the end of its file; page variables (cleared on loading) follow
ovl_intro_vsize	equ 0		; its page variables; its local memory is the rest, to #8000
			ASSERT ovl_intro_end + ovl_intro_vsize <= #8000, "page Intro (title) is more than 16K (code and page variables)"
			DISPLAY "page Intro (PAGES.001):"
			DISPLAY "  title ", /D, ovl_intro__0_e - ovl_intro__0_s
			DISPLAY "  page variables ", /D, ovl_intro_vsize, ", free ", /D, #8000 - (ovl_intro_end + ovl_intro_vsize)
			SAVEAMSDOS "PAGES.001", ovl_intro_start, ovl_intro_end - ovl_intro_start, #4000

; ============================================================
; Page Stage1 -> PAGES.002: level1, maths, stars - threads built to run at #4000
; (a RAM page, or the overlay area); their variables are in the program, but for
; Private Paged ones (after the code). Written as its own file.
; ============================================================
			ORG #4000
ovl_stage1_start:
			dw NTC_STAMP		; the build stamp: the loader checks it against the program's
ovl_stage1__0_s:		; level1
p_level1_play:

			; Level1.cls 3: Dim i As Integer

			; Level1.cls 4: For i = 1 To 3
			dw kw_ltov, 1, var_level1_play_i
for1_t:

			; Level1.cls 5: Score.Add Maths.Square(i)
			dw p_maths_square_cl, var_level1_play_i
			dw p_score_add_c, var_maths_square_square

			; Level1.cls 6: Stars.Add
			dw p_stars_add_cl

			; Level1.cls 7: Next
			dw kw_next1l_n, var_level1_play_i, 3, for1_t
for1_e:

			; Level1.cls 8: Print "Level 1: score "; Score.Total(); ", stars here "; Stars.Count()
			dw p_score_total_c
			dw kw_printzoscii
			dw glyph_4C, glyph_65, glyph_76, glyph_65, glyph_6C, glyph_20, glyph_31, glyph_3A
			dw glyph_20, glyph_73, glyph_63, glyph_6F, glyph_72, glyph_65, glyph_20, 0		; "Level 1: score "
			dw kw_printint, var_score_total_total
			dw p_stars_count_cl
			dw kw_printzoscii
			dw glyph_2C, glyph_20, glyph_73, glyph_74, glyph_61, glyph_72, glyph_73, glyph_20
			dw glyph_68, glyph_65, glyph_72, glyph_65, glyph_20, 0		; ", stars here "
			dw kw_printint, var_stars_count_count
			dw kw_printnl
			dw p_level1_play_r
ovl_stage1__0_e:
ovl_stage1__1_s:		; maths
p_maths_square:

			; Maths.cls 3: Square = n * n
			dw kw_mulvv, var_maths_square_n, var_maths_square_n, var_maths_square_square
			dw p_maths_square_r
ovl_stage1__1_e:
ovl_stage1__2_s:		; stars
p_stars_add:

			; Stars.cls 4: n = n + 1
			dw kw_inc, var_stars_n
			dw p_stars_add_r
p_stars_count:

			; Stars.cls 7: Count = n
			dw kw_vtov, var_stars_n, var_stars_count_count
			dw p_stars_count_r
ovl_stage1__2_e:
; calls from this page into it (no page switch), GOTO / GOSUB of copies
ovl_stage1__x_s:
p_maths_square_cl:			ld hl, p_maths_square	; this page's copy
			ld (ntc_ovl_body), hl
			ld a, 1
			ld (ntc_ovl_lc), a
			jp p_maths_square_c
p_stars_add_cl:			ld hl, p_stars_add	; this page's copy
			ld (ntc_ovl_body), hl
			ld a, 1
			ld (ntc_ovl_lc), a
			jp p_stars_add_c
p_stars_count_cl:			ld hl, p_stars_count	; this page's copy
			ld (ntc_ovl_body), hl
			ld a, 1
			ld (ntc_ovl_lc), a
			jp p_stars_count_c
ovl_stage1__x_e:
			dw 0			; (never empty)
ovl_stage1_end:		; the end of its file; page variables (cleared on loading) follow
var_stars_n		equ ovl_stage1_end + 0		; 2 bytes (stars)
ovl_stage1_vsize	equ 2		; its page variables; its local memory is the rest, to #8000
			ASSERT ovl_stage1_end + ovl_stage1_vsize <= #8000, "page Stage1 (level1, maths, stars) is more than 16K (code and page variables)"
			DISPLAY "page Stage1 (PAGES.002):"
			DISPLAY "  level1 ", /D, ovl_stage1__0_e - ovl_stage1__0_s
			DISPLAY "  maths (home) ", /D, ovl_stage1__1_e - ovl_stage1__1_s
			DISPLAY "  stars (home) ", /D, ovl_stage1__2_e - ovl_stage1__2_s
			DISPLAY "  (local entries, stubs) ", /D, ovl_stage1__x_e - ovl_stage1__x_s
			DISPLAY "  page variables ", /D, ovl_stage1_vsize, ", free ", /D, #8000 - (ovl_stage1_end + ovl_stage1_vsize)
			SAVEAMSDOS "PAGES.002", ovl_stage1_start, ovl_stage1_end - ovl_stage1_start, #4000

