; calls from this page into it (no page switch), GOTO / GOSUB of copies
ovl_stage2__x_s:
p_maths_square_cl__stage2:			ld hl, p_maths_square__stage2	; this page's copy
			ld (ntc_ovl_body), hl
			ld a, 1
			ld (ntc_ovl_lc), a
			jp p_maths_square_c
p_stars_add_cl__stage2:			ld hl, p_stars_add__stage2	; this page's copy
			ld (ntc_ovl_body), hl
